// Parse the Meta Lead Ads webhook payload.
// Meta sends an array of 'entry' objects, each containing 'changes'.
const body = $input.first().json.body;

const entries = body?.entry || [];
const leads = [];

for (const entry of entries) {
  for (const change of (entry.changes || [])) {
    if (change.field === 'leadgen') {
      const value = change.value || {};
      leads.push({
        leadgen_id:   value.leadgen_id   || '',
        page_id:      value.page_id      || '',
        ad_id:        value.ad_id        || '',
        form_id:      value.form_id      || '',
        campaign_id:  value.ad_id        || '',
        created_time: value.created_time
          ? new Date(value.created_time * 1000).toISOString()
          : new Date().toISOString(),
      });
    }
  }
}

if (leads.length === 0) {
  // Verification ping from Meta — respond 200, stop processing
  return [];
}

return leads.map(l => ({ json: l }));

// Flatten the field_data array returned by Graph API into a plain object.
// field_data = [{ name: 'full_name', values: ['John Doe'] }, ...]
const item = $input.first().json;
const fields = {};
for (const f of (item.field_data || [])) {
  fields[f.name] = (f.values || [])[0] || null;
}

return [{
  json: {
    leadgen_id:    item.id,
    full_name:     fields.full_name   || fields.name     || null,
    phone:         fields.phone_number || fields.phone   || null,
    email:         fields.email                          || null,
    city:          fields.city                           || null,
    ad_name:       item.ad_name       || null,
    campaign_name: item.campaign_name || null,
    form_id:       item.form_id       || null,
    created_at:    item.created_time
      ? new Date(item.created_time * 1000).toISOString()
      : new Date().toISOString(),
    status:        'new',
  }
}];
